macro.command:
// Divine Word — apply HP-threshold effects to targets that failed their save
const failedTargets = Array.from(workflow.failedSaves);
if (!failedTargets.length) return;

for (const token of failedTargets) {
  const hp = token.actor?.system?.attributes?.hp?.value ?? 0;
  if (hp <= 0) continue;

  if (hp <= 20) {
    // 0-20 HP: the target dies
    await token.actor.update({"system.attributes.hp.value": 0});
    await MidiQOL.applyTokenDamage([{damage: hp, type: "none"}], hp, new Set([token]), workflow.item, new Set(), {forceApply: true});
  } else if (hp <= 30) {
    // 21-30 HP: Blinded, Deafened, and Stunned for 1 hour
    const effect = workflow.item.effects.find(e => e._id === "dvnWrdAllThree00" || e.name.includes("Stunned"));
    if (effect) await MidiQOL.socket().executeAsGM("createEffects", {actorUuid: token.actor.uuid, effects: [effect.toObject()]});
  } else if (hp <= 40) {
    // 31-40 HP: Blinded and Deafened for 10 minutes
    const effect = workflow.item.effects.find(e => e._id === "dvnWrdBlndDeaf00" || (e.name.includes("Blinded") && !e.name.includes("Stunned")));
    if (effect) await MidiQOL.socket().executeAsGM("createEffects", {actorUuid: token.actor.uuid, effects: [effect.toObject()]});
  } else if (hp <= 50) {
    // 41-50 HP: Deafened for 1 minute
    const effect = workflow.item.effects.find(e => e._id === "dvnWrdDeafened00" || (e.name.includes("Deafened") && !e.name.includes("Blinded")));
    if (effect) await MidiQOL.socket().executeAsGM("createEffects", {actorUuid: token.actor.uuid, effects: [effect.toObject()]});
  }
  // 51+ HP: no effect

  // Extraplanar creatures (Celestial, Elemental, Fey, Fiend) are forced back to their plane
  const creatureType = token.actor?.system?.details?.type?.value?.toLowerCase() ?? "";
  if (["celestial", "elemental", "fey", "fiend"].includes(creatureType)) {
    const td = token.document ?? token;
    await td.update({hidden: true});
    ui.notifications.info(`${token.name} (${creatureType}) is banished back to its plane of origin by Divine Word and cannot return for 24 hours!`);
  }
}
